#!/usr/bin/env node
// Regenerates src/content/reels.generated.ts from every JSON file in
// src/content/reels, so new reels are picked up by Remotion and the local
// renderer without hand-editing imports. Run automatically by render/validate.
import fs from 'node:fs';
import path from 'node:path';
import {REELS_DIR, ROOT, listReels} from './lib.mjs';

export const syncRegistry = () => {
  const ids = listReels().sort();
  const ident = (id) => 'r_' + id.replace(/[^a-zA-Z0-9]/g, '_');
  const lines = [
    '// AUTO-GENERATED by scripts/sync-registry.mjs. Do not edit by hand.',
    "import type {ReelConfig} from './schema';",
    ...ids.map((id) => `import ${ident(id)} from './reels/${id}.json';`),
    '',
    `export const GENERATED_REELS = [${ids.map(ident).join(', ')}] as unknown as ReelConfig[];`,
    '',
  ];
  const out = path.join(ROOT, 'src', 'content', 'reels.generated.ts');
  const next = lines.join('\n');
  if (!fs.existsSync(out) || fs.readFileSync(out, 'utf8') !== next) fs.writeFileSync(out, next);
  return ids;
};

if (import.meta.url === `file://${process.argv[1]}`) {
  const ids = syncRegistry();
  console.log(`Registry: ${ids.length} reel(s) from ${path.relative(ROOT, REELS_DIR)}`);
}
